from collections import deque

def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # BFS with queue, keeping track of distances
    dist = [-1] * n
    dist[s] = 0
    q = deque([s])

    while q:
        u = q.popleft()
        for v, w in adj[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + w
                q.append(v)
            else:
                # If a shorter path is found, update and requeue
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    q.append(v)

    return dist[t] if dist[t] != -1 else -1
