def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0]) if rows else 0

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    if not is_valid(start[0], start[1]) or not is_valid(goal[0], goal[1]):
        return []

    if start == goal:
        return [start]

    visited = set()
    path = {}
    stack = [start]

    while stack:
        current = stack.pop()
        if current == goal:
            break
        if current in visited:
            continue
        visited.add(current)
        r, c = current
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc) and (nr, nc) not in visited:
                stack.append((nr, nc))
                path[(nr, nc)] = current

    if goal not in path:
        return []

    # Reconstruct path
    current = goal
    route = [current]
    while current != start:
        current = path[current]
        route.append(current)
    return route[::-1]
