    if start == goal:
        return [start]

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Helper function to check if a cell is valid
    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    # Helper function to find a path using backtracking
    def backtrack(path):
        current = path[-1]
        if current == goal:
            return path.copy()
        for dr, dc in directions:
            next_r, next_c = current[0] + dr, current[1] + dc
            if is_valid(next_r, next_c) and (next_r, next_c) not in path:
                path.append((next_r, next_c))
                result = backtrack(path)
                if result:
                    return result
                path.pop()
        return None

    return backtrack([start])
