def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0]) if rows else 0

    def is_valid(pos):
        r, c = pos
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    if not is_valid(start) or not is_valid(goal):
        return []

    if start == goal:
        return [start]

    # Use Dijkstra's algorithm with a priority queue (heapq)
    import heapq
    heap = [(0, start)]
    came_from = {}
    visited = set()

    while heap:
        _, current = heapq.heappop(heap)
        if current == goal:
            break
        if current in visited:
            continue
        visited.add(current)
        r, c = current
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            neighbor = (r + dr, c + dc)
            if is_valid(neighbor) and neighbor not in visited:
                came_from[neighbor] = current
                heapq.heappush(heap, (len(came_from), neighbor))

    # Reconstruct path
    path = []
    current = goal
    while current != start:
        path.append(current)
        current = came_from.get(current, None)
        if current is None:
            return []
    path.append(start)
    return path[::-1]
