        return []

    if start == goal:
        return [start]

    # Use a priority queue with a heuristic to guide the search (A* algorithm)
    import heapq

    def heuristic(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    pq = [(heuristic(start, goal), 0, start, [])]
    visited = set()

    while pq:
        _, cost, current, path = heapq.heappop(pq)
        if current in visited:
            continue
        visited.add(current)
        path = path + [current]
        if current == goal:
            return path
        r, c = current
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc) and (nr, nc) not in visited:
                heapq.heappush(pq, (cost + 1 + heuristic((nr, nc), goal), cost + 1, (nr, nc), path))
    return []
