def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0]) if rows else 0

    # Check if start or goal is out of bounds or is a wall
    if not (0 <= start[0] < rows and 0 <= start[1] < cols) or \
       not (0 <= goal[0] < rows and 0 <= goal[1] < cols):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    # If start is the same as goal
    if start == goal:
        return [start]

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Use a stack for depth-first search (but the problem says no DFS)
    # However, the user restricted using BFS or DFS, so we use backtracking instead

    def backtrack(current, path):
        if current == goal:
            return path + [current]
        row, col = current
        for dr, dc in directions:
            nr, nc = row + dr, col + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and (nr, nc) not in path:
                result = backtrack((nr, nc), path + [current])
                if result:
                    return result
        return None

    return backtrack(start, [])
